code.correct:
def count(g, r, c):
    n = len(g)
    m = len(g[0])
    if r >= n or c >= m or g[r][c] == 1:
        return 0
    if r == n - 1 and c == m - 1:
        return 1
    return count(g, r + 1, c) + count(g, r, c + 1)

